import { createFileRoute, Link } from "@tanstack/react-router";
import {
  Activity,
  AlertTriangle,
  Archive,
  ArrowRight,
  Bell,
  Clock,
  HelpCircle,
  Plus,
} from "lucide-react";
import type { LucideIcon } from "lucide-react";

import { useCaseViews } from "../data/caseViews";
import type { Tone } from "../data/lottoDemoCases";

export const Route = createFileRoute("/")({
  head: () => ({
    meta: [
      { title: "Fallmonitor – Muc Legal Monitoring" },
      {
        name: "description",
        content: "Übersicht über Fälle und Monitoringläufe zu Unterlassungserklärungen.",
      },
      { property: "og:title", content: "Fallmonitor – Muc Legal Monitoring" },
      {
        property: "og:description",
        content: "Übersicht über Fälle und Monitoringläufe zu Unterlassungserklärungen.",
      },
      { property: "og:type", content: "website" },
      { name: "twitter:card", content: "summary" },
    ],
  }),
  component: Index,
});

const toneIcon: Record<Tone, LucideIcon> = {
  danger: AlertTriangle,
  success: Activity,
  warning: HelpCircle,
  neutral: Clock,
};

const toneLabel: Record<Tone, string> = {
  danger: "Kritisch",
  success: "In Ordnung",
  warning: "Prüfung nötig",
  neutral: "Ausstehend",
};

const toneColor: Record<Tone, string> = {
  danger: "text-danger bg-danger/10",
  success: "text-success bg-success/10",
  warning: "text-warning bg-warning/10",
  neutral: "text-muted-foreground bg-muted",
};

function relativeTime(iso: string | null, now = new Date()) {
  if (!iso) return "geplant";
  const mins = Math.max(1, Math.round((now.getTime() - new Date(iso).getTime()) / 60000));
  if (mins < 60) return `vor ${mins} Min.`;
  const hours = Math.round(mins / 60);
  if (hours < 24) return `vor ${hours} Std.`;
  return `vor ${Math.round(hours / 24)} Tg.`;
}

function formatDateTime(date: Date) {
  return date.toLocaleString("de-DE", {
    day: "2-digit",
    month: "2-digit",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit",
    timeZone: "Europe/Berlin",
  });
}

function Index() {
  const { cases, demoMode, isError } = useCaseViews();
  const now = new Date();
  const oneDayAgo = new Date(now.getTime() - 24 * 60 * 60 * 1000);
  const newCount = cases.filter(
    (item) => item.found_at && new Date(item.found_at) > oneDayAgo,
  ).length;
  const criticalCount = cases.filter((item) => item.tone === "danger").length;
  const inReviewCount = cases.filter(
    (item) => item.tone === "warning" || item.tone === "neutral",
  ).length;
  const lastRun =
    cases
      .map((item) => item.found_at)
      .filter((value): value is string => Boolean(value))
      .sort()
      .at(-1) ?? null;
  const nextRun = new Date(now.getTime() + 2 * 60 * 60 * 1000);
  const topPriorities = cases
    .filter((item) => item.tone === "danger")
    .sort(
      (a, b) =>
        (b.found_at ? new Date(b.found_at).getTime() : 0) -
        (a.found_at ? new Date(a.found_at).getTime() : 0),
    )
    .slice(0, 3);

  return (
    <div className="mx-auto max-w-5xl px-8 py-12">
      <div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
        <div>
          <h1 className="text-3xl">Dashboard</h1>
          <p className="mt-2 text-sm text-muted-foreground">
import { createFileRoute } from "@tanstack/react-router";
import { useQueryClient } from "@tanstack/react-query";
import { AlertTriangle, CheckCircle2, ChevronDown, Clock, HelpCircle, Scale } from "lucide-react";
import { useState } from "react";

import { useCaseViews } from "../data/caseViews";
import type { Tone } from "../data/lottoDemoCases";
import {
  getMonitoringRun,
  monitoringCasesQueryKey,
  reviewMonitoringCase,
  startMonitoringRun,
} from "../lib/monitoring-api";

export const Route = createFileRoute("/hinweise")({
  head: () => ({
    meta: [
      { title: "Hinweise – Muc Legal Monitoring" },
      {
        name: "description",
        content:
          "Aktuelle Hinweise aus dem Monitoring als Benachrichtigungen – mit Zeitstempel, Kontext und vollständiger Beweisführung.",
      },
      { property: "og:title", content: "Hinweise – Muc Legal Monitoring" },
      {
        property: "og:description",
        content:
          "Aktuelle Hinweise aus dem Monitoring als Benachrichtigungen – mit Zeitstempel, Kontext und vollständiger Beweisführung.",
      },
      { property: "og:type", content: "website" },
      { name: "twitter:card", content: "summary" },
    ],
  }),
  component: HinweisePage,
});

const toneIcon: Record<Tone, typeof Scale> = {
  danger: AlertTriangle,
  success: CheckCircle2,
  warning: HelpCircle,
  neutral: Clock,
};

const toneColor: Record<Tone, string> = {
  danger: "text-danger bg-danger/10",
  success: "text-success bg-success/10",
  warning: "text-warning bg-warning/10",
  neutral: "text-muted-foreground bg-muted",
};

const toneLabel: Record<Tone, string> = {
  danger: "Kritisch",
  success: "In Ordnung",
  warning: "Prüfung nötig",
  neutral: "Ausstehend",
};

function relativeTime(iso: string | null) {
  if (!iso) return "geplant";
  const now = Date.now();
  const mins = Math.max(1, Math.round((now - new Date(iso).getTime()) / 60000));
  if (mins < 60) return `vor ${mins} Min.`;
  const hours = Math.round(mins / 60);
  if (hours < 24) return `vor ${hours} Std.`;
  return `vor ${Math.round(hours / 24)} Tg.`;
}

function formatDateTime(iso: string | null) {
  if (!iso) return "—";
  return new Date(iso).toLocaleString("de-DE", {
    day: "2-digit",
    month: "2-digit",
    year: "numeric",
    hour: "2-digit",
    minute: "2-digit",
    timeZone: "Europe/Berlin",
  });
}

function HinweisePage() {
  const { cases } = useCaseViews();
  const queryClient = useQueryClient();
  const [openId, setOpenId] = useState<string | null>(null);
  const [actionState, setActionState] = useState<Record<string, string>>({});

  async function decide(caseId: string, decision: "freigegeben" | "abgelehnt") {
    setActionState((state) => ({ ...state, [caseId]: "Entscheidung wird gespeichert …" }));
    try {
      await reviewMonitoringCase(caseId, decision);
      await queryClient.invalidateQueries({ queryKey: monitoringCasesQueryKey });
      setActionState((state) => ({
        ...state,
        [caseId]: decision === "freigegeben" ? "Fall wurde freigegeben." : "Fall wurde abgelehnt.",
      }));
    } catch (error) {
      setActionState((state) => ({
        ...state,
        [caseId]: error instanceof Error ? error.message : "Entscheidung fehlgeschlagen.",
      }));
    }

