        for field in (
            "kerngleich_umfasst",
            "nicht_umfasst",
            "rechtsgrundlagen",
            "offene_fragen",
        ):
            value[field] = list(value[field])
        return value

    def to_monitoring_tenor(self) -> dict[str, Any]:
        return {
